  vocab=[V("v-watersnoodramp","watersnoodramp","catástrofe das cheias","noun","de"), V("v-deltawerken","Deltawerken","Obras do Delta","noun","de"),
         V("v-stormvloedkering","stormvloedkering","barreira contra tempestades","noun","de"), V("v-beschermen","beschermen","proteger","verb")],
  ex=[("In 1953 was er een grote watersnoodramp in Zeeland.","Em 1953 houve uma grande catástrofe de cheias na Zelândia."),("Daarna werden de Deltawerken gebouwd.","Depois foram construídas as Obras do Delta."),("De stormvloedkering gaat dicht bij hoog water.","A barreira fecha quando a água sobe."),("De dijken beschermen het land.","Os diques protegem o país.")],
  review=["v-dijk","v-overstroming","v-zeespiegel"],
