    MC("Kinderdijk é conhecido pelos seus…", ["*moinhos de vento","túlipas|Não especialmente.","queijos|Não."], "Património Mundial.", ["v-windmolen"]),
    FE(["Het","water","wordt","weggepompen."], 3, "weggepompt", "pompen → gepompt.", ["v-wegpompen"]),
    FB("Zonder ___ zou de polder onder water staan.", ["gemalen"], "Estações de bombagem.", ["v-gemaal"], choices=["gemalen","windmolens","dijken"], tr="Sem estações de bombagem, o pólder estaria debaixo de água."),
    LI("Het waterschap zorgt voor droge voeten.", ["Het waterschap zorgt voor droge voeten"], "O instituto da água garante que não ficamos com os pés molhados.", "Expressão.", ["v-droog-houden"]),
    WO("O pólder fica seco.", ["De","polder","blijft","droog"], "Ordem.", ["v-droog-houden"]),
